using System;using System.IO;using System.Net;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Security.Cryptography;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Diagnostics;
class TransferTest {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static string Hash(byte[] b){using(var s=SHA256.Create())return DownloadSetup.Hex(s.ComputeHash(b));}
 static void Reject(Action action,string text){bool failed=false;try{action();}catch(IOException){failed=true;}Check(failed,text);}
 static int Main(string[] args){try{Run(args[0]);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(string root){Directory.CreateDirectory(root);byte[] a=new byte[SetupTransfer.BlockSize+1024*1024],b=new byte[SetupTransfer.BlockSize+1024*1024];new Random(42).NextBytes(a);new Random(43).NextBytes(b);byte[] all=new byte[a.Length+b.Length];Buffer.BlockCopy(a,0,all,0,a.Length);Buffer.BlockCopy(b,0,all,a.Length,b.Length);var m=new DownloadManifest{format=1,version="0.0.0",output="EFTGPS-Test-Setup.exe",size=all.Length,sha256=Hash(all),parts=new[]{new DownloadPart{name="EFTGPS-Test-Setup.exe.part01",size=a.Length,sha256=Hash(a)},new DownloadPart{name="EFTGPS-Test-Setup.exe.part02",size=b.Length,sha256=Hash(b)}}};
 var listener=new HttpListener();var sock=new System.Net.Sockets.TcpListener(IPAddress.Loopback,0);sock.Start();int port=((IPEndPoint)sock.LocalEndpoint).Port;sock.Stop();string url="http://127.0.0.1:"+port+"/";listener.Prefixes.Add(url);listener.Start();int requests=0,mode=0;bool alive=true;var server=Task.Run(()=>{while(alive){HttpListenerContext ctx;try{ctx=listener.GetContext();}catch{break;}ThreadPool.QueueUserWorkItem(delegate{try{int number=Interlocked.Increment(ref requests);if(mode==1&&number==1){ctx.Response.StatusCode=503;ctx.Response.Close();return;}var range=ctx.Request.Headers["Range"].Substring(6).Split('-');long start=long.Parse(range[0]),end=long.Parse(range[1]);byte[] data=ctx.Request.Url.AbsolutePath=="/0"?a:b;ctx.Response.StatusCode=206;ctx.Response.ContentLength64=end-start+1;ctx.Response.Headers["Content-Range"]="bytes "+(mode==2?start+1:start)+"-"+end+"/"+data.Length;for(long offset=start;offset<=end;offset+=65536){int n=(int)Math.Min(65536,end-offset+1);ctx.Response.OutputStream.Write(data,(int)offset,n);}ctx.Response.Close();}catch{try{ctx.Response.Abort();}catch{}}});}});
 Func<int,long,long,HttpWebRequest> factory=delegate(int part,long start,long length){var r=(HttpWebRequest)WebRequest.Create(url+part);r.Proxy=null;r.Timeout=2000;r.ReadWriteTimeout=2000;r.AddRange(start,start+length-1);return r;};
 try{mode=1;string cache=Path.Combine(root,"cache");var phases=new HashSet<string>();string file=SetupTransfer.Run(m,cache,CancellationToken.None,null,delegate(string p,long x,long total){lock(phases)phases.Add(p);},factory);Check(File.ReadAllBytes(file).Length==all.Length,"length");Check(phases.Contains("retry")&&phases.Contains("verify"),"Visible retry and verification");int before=requests;SetupTransfer.Run(m,cache,CancellationToken.None,null,null,factory);Check(requests==before,"Verified cached blocks downloaded again");
 using(var stream=File.Open(file,FileMode.Open,FileAccess.Write)){stream.Position=10;stream.WriteByte((byte)(a[10]^1));}Reject(()=>SetupTransfer.Run(m,cache,CancellationToken.None,null,null,factory),"Corrupt cache accepted");before=requests;SetupTransfer.Run(m,cache,CancellationToken.None,null,null,factory);Check(requests-before==2,"Unchanged part was downloaded again");
 using(var lease=File.Open(file+".lock",FileMode.Open,FileAccess.ReadWrite,FileShare.None))Reject(()=>SetupTransfer.Run(m,cache,CancellationToken.None,null,null,factory),"Concurrent writers accepted");
 mode=2;Reject(()=>SetupTransfer.Run(m,Path.Combine(root,"wrong-range"),CancellationToken.None,null,null,factory),"Invalid Content-Range accepted");mode=0;
 var cancel=new CancellationTokenSource();bool cancelled=false;try{SetupTransfer.Run(m,Path.Combine(root,"cancel"),cancel.Token,delegate(long x,int i){if(x>1024*1024)cancel.Cancel();},null,factory);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"Cancellation ignored");SetupTransfer.Run(m,Path.Combine(root,"cancel"),CancellationToken.None,null,null,factory);
 Console.WriteLine("Download tests passed: range validation, bounded retry, offline reuse, corruption recovery, unchanged-part resume, exclusive writer and cancellation.");
 }finally{alive=false;listener.Stop();listener.Close();server.Wait(2000);}
 }
}
